def verify_capture(source,result):
    if result['feature_count']!=result['source_count']:
        raise ValueError('incomplete')

def collect(source):
    rows=[dict(r) for r in source[:-1]]
    result={'rows':rows,'feature_count':len(rows),'source_count':len(rows)}
    verify_capture(source,result)
    return result

